ee:message.ee:set-payload:
%dw 2.0
output application/json
var templateVariablesByName = vars.initialPayload.templateVariables reduce ((item, acc = {}) -> acc ++ {
    (item.name): item.value
  })
---
{
  notification: {
    messageChannel: vars.initialPayload.messageChannel default vars.relatedCampaign[0].channel,
    templateName: vars.relatedCampaign[0].pauConfig.templateName default vars.relatedCampaign[0].campaignName,
    receiverPhoneNumber: vars.initialPayload.receiver.phoneNumber,
    templateVariables: (vars.relatedCampaign[0].defaultVariables map (defaultVar) -> do {
        var templateValue = templateVariablesByName[defaultVar.name]
        var finalValue = if ((templateValue != null) and (defaultVar.overridable default false))
          templateValue
        else
          defaultVar.value
        ---
        defaultVar - "value" ++ {
          value: finalValue
        }
      }).value
  }
}

%dw 2.0
output application/json  
var templateVariablesByName = vars.initialPayload.templateVariables reduce ((item, acc = {}) -> acc ++ {
    (item.name): item
  })

---
{
  "correlationId": correlationId,
  "channel": vars.initialPayload.messageChannel default vars.relatedCampaign[0].channel,
  "campaignName": vars.relatedCampaign[0].responsysConfig.campaignName default vars.relatedCampaign[0].campaignName,
  "recipients": [
    {
      "customerId": vars.initialPayload.receiver.documentNumber,
      ("emailAddress": vars.initialPayload.receiver.email) if (vars.initialPayload.messageChannel == "EMAIL"),
      ("mobileNumber": vars.initialPayload.receiver.phoneNumber) if (vars.initialPayload.messageChannel == "SMS"),
      "listFolderName": vars.relatedCampaign[0].responsysConfig.folderName,
      "listObjectName": vars.relatedCampaign[0].responsysConfig.listObjectName,
      "optionalData": (vars.relatedCampaign[0].defaultVariables map (defaultVar) -> do {
          var templateVar = templateVariablesByName[defaultVar.name]
          ---
          if ((templateVar != null) and (defaultVar.overridable default false))
            templateVar
          else
            defaultVar - "overridable"
        })
    }
  ]
}
